css:
.af-controls { display: flex; flex-wrap: wrap; gap: 12px; justify-content: flex-end; }
.af-search, .af-country { height: 48px; padding: 0 16px; border-radius: 6px; border: 1px solid rgba(255,255,255,0.14); background: rgba(4,28,48,0.7); color: #eaf2f8; font-family: var(--font-body); font-size: 15px; outline: none; }
.af-search { min-width: 240px; flex: 1 1 240px; max-width: 320px; }
.af-country { min-width: 200px; }
.af-search::placeholder { color: #6f8598; }
.af-search:focus, .af-country:focus { border-color: #00cdfd; }
.af-country option { background: #041c30; color: #eaf2f8; }
.af-count { margin: 18px 0 0; font-size: 13px; letter-spacing: 0.14em; text-transform: uppercase; color: #6f8498; text-align: right; }
.af-empty { padding: 48px 0; text-align: center; color: #9fb4c6; }
.af-empty[hidden] { display: none; }
.af-clear { margin-top: 8px; font-family: var(--font-heading); font-weight: 600; font-size: 13px; letter-spacing: 0.12em; text-transform: uppercase; color: #020617; background: linear-gradient(135deg, #00fbff, #00cdfd); border: 0; padding: 10px 22px; border-radius: 4px; cursor: pointer; }
